"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["48360"],{37243(e){e.exports=JSON.parse('{"tag":{"label":"Care Commitment","permalink":"/docs/tags/care-commitment","allTagsPath":"/docs/tags","count":7,"items":[{"id":"Degus/getting-started/degu-basic-care","title":"Degu Basic Care","description":"Degus are intelligent, social, and diurnal (active during the day) rodents that can make fascinating pets. They require specific care, particularly regarding their diet and social needs, to live a healthy life. This guide covers the essential care routines for degus.","permalink":"/docs/Degus/getting-started/degu-basic-care"},{"id":"Ferrets/getting-started/ferret-basic-care","title":"Ferret Basic Care","description":"Ferrets are playful, curious, and energetic members of the weasel family. They can make wonderful, engaging pets, but they have very specific care requirements that differ significantly from rodents. Understanding their needs is key to providing a healthy and enriching life.","permalink":"/docs/Ferrets/getting-started/ferret-basic-care"},{"id":"Gerbils/getting-started/gerbil-basic-care","title":"Gerbil Basic Care","description":"Gerbils are relatively low-maintenance pets, but they have specific needs that must be met to ensure they live a long, healthy, and happy life. This guide covers the fundamentals of daily, weekly, and monthly care for your gerbils.","permalink":"/docs/Gerbils/getting-started/gerbil-basic-care"},{"id":"Hamsters/getting-started/hamster-basic-care","title":"Hamster Basic Care","description":"Hamsters are popular pets, known for their chubby cheeks and love of running on their wheel. While they are small, they still require consistent care to thrive. This guide covers the daily, weekly, and monthly tasks needed to keep your hamster healthy and happy.","permalink":"/docs/Hamsters/getting-started/hamster-basic-care"},{"id":"Hedgehogs/getting-started/hedgehog-basic-care","title":"Hedgehog Basic Care","description":"Hedgehogs are unique and charming pets, but they have very specific care needs that are critical to their survival and well-being. Unlike more common small pets, they are not low-maintenance and require a dedicated owner to thrive. This guide covers the essential aspects of hedgehog care.","permalink":"/docs/Hedgehogs/getting-started/hedgehog-basic-care"},{"id":"Gerbils/getting-started/is-a-gerbil-right-for-me","title":"Is a Gerbil Right for You?","description":"Gerbils are curious, active, and social animals that can make wonderful pets for the right family. However, like any animal, they have specific needs that must be met to ensure they live a happy and...","permalink":"/docs/Gerbils/getting-started/is-a-gerbil-right-for-me"},{"id":"Mice/getting-started/mouse-basic-care","title":"Mouse Basic Care","description":"Mice are intelligent, social, and active little animals that can make engaging pets. Proper care is essential to ensure they live a full and stimulating life. This guide outlines the key aspects of caring for pet mice.","permalink":"/docs/Mice/getting-started/mouse-basic-care"}],"unlisted":false}}')}}]);